"""Seat students in rows of seats, ordered by last name."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

def _name_order(student: Student) -> Tuple[str, str]:
    last = student.last_name.casefold()
    first = student.first_name.casefold()
    return (last, first)

def _check_input(
    ordered: List[Student], seats: int
) -> None:
    if seats <= 0:
        raise ValueError(f"seats must be positive: {seats}")
    if not ordered:
        raise ValueError("no students to seat")

def _split_rows(
    ordered: List[Student], seats: int
) -> List[List[Student]]:
    starts = range(0, len(ordered), seats)
    return [ordered[step:step + seats] for step in starts]

def _format_rows(groups: List[List[Student]]) -> List[str]:
    rows = []
    for number, group in enumerate(groups, 1):
        names = [student.display_name for student in group]
        rows.append(f"Row {number}: {' | '.join(names)}")
    return rows

# ---
def seat_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    ordered = sorted(students, key=_name_order)
    _check_input(ordered, seats_per_row)
    groups = _split_rows(ordered, seats_per_row)
    return _format_rows(groups)
